const fs=require("fs"),crypto=require("crypto");
const CONTROL="/home/node/.n8n-files/control";
const REQUEST=CONTROL+"/production_handoff.request.json";
const RESPONSE=CONTROL+"/production_handoff.response.json";
const SCHEMA="quant-control-action/v1",RESPONSE_SCHEMA="quant-control-action-response/v1";
const ACTION="runtime_observe_once",ENVELOPE="quant-control-plane-runtime-observation-source/v1";
const OBSERVATION="quant-runtime-observation/v1";
const REQUEST_ID="n8n-"+crypto.randomUUID();
const DEADLINE_MS=180000,POLL_MS=500;
const sleep=(ms)=>new Promise((resolve)=>setTimeout(resolve,ms));
const envelope=(invocation,body,gap)=>{
  const out={schema:ENVELOPE,action:ACTION,request_id:REQUEST_ID,invocation:invocation,family_id:null,observation:null,gap:gap||null};
  if(body&&typeof body==="object"){
    out.observation=body;
    const current=body.current||{};
    out.family_id=(typeof current.family_id==="string"&&current.family_id.length)?current.family_id:null;
  }
  return out;
};
const emit=(payload)=>{process.stdout.write(JSON.stringify(payload)+"\n");};
(async()=>{
  const payload=JSON.stringify({schema:SCHEMA,action:ACTION,request_id:REQUEST_ID});
  const tmp=CONTROL+"/.runtime_observe."+process.pid+"."+crypto.randomUUID()+".tmp";
  let fd=null;
  try{
    fs.mkdirSync(CONTROL,{recursive:true});
    fd=fs.openSync(tmp,"wx",0o600);
    fs.writeFileSync(fd,payload,{encoding:"utf8"});
    fs.fsyncSync(fd);
    fs.closeSync(fd);
    fd=null;
    try{fs.linkSync(tmp,REQUEST);}finally{try{fs.unlinkSync(tmp);}catch(error){}}
  }catch(error){
    if(fd!==null){try{fs.closeSync(fd);}catch(closeError){}}
    try{fs.unlinkSync(tmp);}catch(unlinkError){}
    emit(envelope({status:"request_publish_failed",exit_code:null,detail:String((error&&error.message)||error)},null,null));
    return;
  }
  const deadline=Date.now()+DEADLINE_MS;
  while(Date.now()<deadline){
    let response=null;
    try{
      const stat=fs.lstatSync(RESPONSE);
      if(!stat.isFile()||stat.isSymbolicLink())throw new Error("response_not_regular");
      response=JSON.parse(fs.readFileSync(RESPONSE,"utf8"));
    }catch(error){response=null;}
    if(response&&response.schema===RESPONSE_SCHEMA&&response.request_id===REQUEST_ID&&response.action===ACTION){
      const invocation={status:response.status,exit_code:response.exit_code,started_at_utc:response.started_at_utc,finished_at_utc:response.finished_at_utc};
      let body=null,gap=null;
      try{
        const parsed=JSON.parse(response.stdout);
        if(parsed&&parsed.schema===OBSERVATION){body=parsed;}
        else{gap="observation payload does not carry schema "+OBSERVATION;}
      }catch(error){
        gap="observation stdout is not a readable JSON document (truncated or unparsable): "+String((error&&error.message)||error);
      }
      emit(envelope(invocation,body,gap));
      return;
    }
    await sleep(POLL_MS);
  }
  emit(envelope({status:"response_timeout",exit_code:null,detail:"no correlated response within "+DEADLINE_MS+" ms; the host bridge may be unavailable"},null,null));
})();
'

