// SHADOW MODE assembler — deterministic, read-only.
// Inputs: stdout JSON from read-only Execute Command source nodes (cat/ls/wc/sha256sum/node-read projections only).
// Output: one machine-readable shadow snapshot item (+ binary copy for the single output node).
// This node performs no writes, no network access and no control-plane mutation.

const VOCAB = {
  WAITING_DATA: 'candidate prerequisite/data missing but potentially recoverable',
  READY_TO_RESUME: 'previously waiting candidate whose prerequisite is now satisfied (policy: never interrupt the running family; takes priority over untouched queue candidates afterwards)',
  BLOCKED: 'genuine abnormal condition requiring intervention; not a synonym for missing data',
  TECHNICAL_INCOMPLETE: 'terminal: an objective prerequisite cannot be satisfied; no automatic resume',
  REJECT: 'terminal scientific/strategy rejection',
  PASS: 'promoted survivor (leaderboard entry)',
  RUNNING_QLIB: 'existing runtime stage: full backtest running',
  ARTIFACT_READY: 'existing runtime stage: artifacts complete, terminal not yet published',
  FAILED_SCRIPT: 'existing runtime stage: run stopped without a published terminal',
};
const TOKEN_ORDER = ['TECHNICAL_INCOMPLETE', 'READY_TO_RESUME', 'WAITING_DATA', 'RUNNING_QLIB', 'ARTIFACT_READY', 'FAILED_SCRIPT', 'BLOCKED', 'REJECT', 'PASS'];
const RT_TOKENS = ['RUNNING_QLIB', 'ARTIFACT_READY', 'FAILED_SCRIPT'];

const NODE = {
  scout: 'Strategy Research — Hermes Scout cron state (read-only)',
  pool: 'Pool — alpha-strategy-research pool (read-only)',
  intake: 'Intake Review — canonical intake state (read-only)',
  gate: 'Preflight Gate — prerequisite evidence (read-only)',
  observation: 'Runtime Observation — canonical runtime evidence (read-only)',
  parking: 'Parking — private survivor repo metadata (read-only)',
};

const gaps = [];
const addGap = (field, reason) => { if (!gaps.some((g) => g.field === field)) gaps.push({ field, reason }); };
const num = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : null);
const str = (v) => (typeof v === 'string' && v.length ? v : null);
const bool = (v) => (typeof v === 'boolean' ? v : null);
const len = (v) => (Array.isArray(v) ? v.length : null);
const get = (o, path) => path.split('.').reduce((a, k) => (a && typeof a === 'object' ? a[k] : undefined), o);

function stdoutOf(name) {
  try {
    const item = $(name).first();
    const s = item && item.json ? item.json.stdout : null;
    return typeof s === 'string' && s.trim().length ? s : null;
  } catch (e) {
    return null;
  }
}
function parseSource(name, label) {
  const text = stdoutOf(name);
  if (text === null) { addGap(label, 'source node returned no stdout (unreadable or empty)'); return null; }
  try { return JSON.parse(text); } catch (e) { addGap(label, 'stdout is not a valid JSON object'); return null; }
}

const scout = parseSource(NODE.scout, 'Hermes Scout cron state');
const pool = parseSource(NODE.pool, 'strategy pool inventory');
const intake = parseSource(NODE.intake, 'canonical intake state');
const gateRec = parseSource(NODE.gate, 'prerequisite gate evidence');
const parking = parseSource(NODE.parking, 'survivor parking metadata');
// The runtime source is the host bridge's on-demand observation of the canonical runtime artifacts
// (never a projection file): one fixed read-only action, correlated by request_id. Invocation
// outcome (did the request reach the host and answer) and pipeline outcome (what the runtime is
// doing) stay separate fields - the envelope carries the first, the body the second.
const envelope = parseSource(NODE.observation, 'runtime observation');
const invocation = envelope && envelope.invocation && typeof envelope.invocation === 'object' ? envelope.invocation : null;
const observation = envelope && envelope.observation && typeof envelope.observation === 'object' ? envelope.observation : null;
if (envelope === null) {
  addGap('runtime_observation', 'the runtime observation source node produced no readable envelope');
} else if (observation === null) {
  addGap('runtime_observation', str(envelope.gap) || 'the runtime observation returned no observation payload');
}
if (invocation && str(invocation.status) && invocation.status !== 'ok') {
  addGap('runtime_observation_invocation', 'host bridge invocation status ' + invocation.status);
}
for (const item of (Array.isArray(get(observation, 'gaps')) ? observation.gaps : [])) {
  addGap('runtime_observation.' + (str(item.field) || 'unknown'), str(item.reason) || 'reported by the runtime observation');
}

const snap = get(intake, 'counts') || null;
const obsCounts = get(observation, 'counts') || null;
const obsCurrent = get(observation, 'current') || null;
const obsHealth = get(observation, 'health') || null;
const obsLeaderboard = get(observation, 'leaderboard') || null;
const obsPool = get(observation, 'pool') || null;
const obsFunnel = get(observation, 'funnel') || null;
const parkMeta = get(parking, 'meta') || null;

// --- gate evidence: project the newest record per family, then adopt the one that matches the
// canonical current family. The n8n side never decides which family is current (the observation
// does); it only looks the matching record up and never invents one when it is absent.
const currentFamilyId = str(get(obsCurrent, 'family_id'));
const gateRecords = Array.isArray(get(gateRec, 'records')) ? get(gateRec, 'records') : [];
const gateRecord = (currentFamilyId !== null
    ? gateRecords.find((item) => item && str(item.family_id) === currentFamilyId) || null
    : null);
const gateMatchedSameFamily = (gateRecord !== null && currentFamilyId !== null)
  ? bool(str(gateRecord.family_id) === currentFamilyId) : null;

const counts = {
  pool_root_md_total: num(get(pool, 'root_md_total')),
  pool_records_total: num(get(pool, 'records')),
  intake_pass: num(get(snap, 'pass')),
  intake_pass_with_caveat: num(get(snap, 'pass_with_caveat')),
  intake_remediate: num(get(snap, 'remediate')),
  intake_reject: num(get(snap, 'reject')),
  intake_pending_ingestion: num(get(snap, 'pending_ingestion')),
  intake_deferred_delta: num(get(snap, 'deferred_delta')),
  intake_ingested_wiki_records: num(get(snap, 'ingested_wiki_records')),
  wiki_reviewed: num(get(obsFunnel, 'wiki_brain.reviewed')),
  wiki_ingested: num(get(obsFunnel, 'wiki_brain.ingested')),
  families_registered: num(get(obsCounts, 'families_registered')),
  families_backtested: num(get(obsCounts, 'families_backtested')),
  families_in_flight: num(get(obsCounts, 'families_in_flight')),
  families_unresolved: num(get(obsCounts, 'families_unresolved')),
  workload_evaluations: num(get(obsCounts, 'workload_evaluations')),
  workload_grid_artifacts: num(get(obsCounts, 'workload_grid_artifacts')),
  candidates_pool_total: num(get(obsCounts, 'candidates_pool_total')),
  candidates_consumed: num(get(obsCounts, 'candidates_consumed')),
  candidates_queued: num(get(obsCounts, 'candidates_queued')),
  candidates_rule: str(get(obsPool, 'rule')),
  last_pipeline_advance_utc: str(get(obsCounts, 'last_pipeline_advance_utc')),
  last_pipeline_advance_family_id: str(get(obsCounts, 'last_pipeline_advance_family_id')),
  leaderboard_count: num(get(obsLeaderboard, 'count')),
  leaderboard_shown: num(get(obsLeaderboard, 'shown')),
  current_family_id: currentFamilyId,
  current_round_id: str(get(obsCurrent, 'round_id')),
  current_attempt: str(get(obsCurrent, 'attempt')),
  current_state: str(get(obsCurrent, 'state')),
  current_stage: str(get(obsCurrent, 'stage')),
  current_verdict: str(get(obsCurrent, 'verdict')),
  current_progress_pct: num(get(obsCurrent, 'progress.pct')),
  current_cohort: str(get(obsCurrent, 'cohort')),
  current_agent_log_at_utc: str(get(obsCurrent, 'agent.agent_log_last_write_utc')),
  current_why: str(get(obsCurrent, 'why')),
  runtime_health_status: str(get(obsHealth, 'status')),
  runtime_health_active_count: num(get(obsHealth, 'active_count')),
  gate_record_count: num(get(gateRec, 'record_count')),
  gate_record_matched_current_family: gateMatchedSameFamily,
  parking_survivor_dirs: num(get(parking, 'survivor_dirs')),
  parking_survivor_count: num(get(parkMeta, 'survivor_count')),
  parking_top10_count: num(get(parkMeta, 'top10_count')),
};

let gateView = null;
if (gateRecord && typeof gateRecord === 'object') {
  const texts = [str(gateRecord.conclusion), str(gateRecord.verdict)].filter((t) => t !== null);
  let token = null;
  let tokenText = null;
  for (const t of texts) {
    const hit = TOKEN_ORDER.find((k) => t.indexOf(k) !== -1);
    if (hit) { token = hit; tokenText = t; break; }
  }
  gateView = {
    record_path: str(gateRecord.path),
    record_sha256: str(gateRecord.sha256),
    record_bytes: num(gateRecord.bytes),
    document_kind: str(gateRecord.document_kind),
    schema_version: num(gateRecord.schema_version),
    family_id: str(gateRecord.family_id),
    round_id: str(gateRecord.round_id),
    kanban_task_id: str(gateRecord.kanban_task_id),
    recorded_at_utc: str(gateRecord.created_at_utc),
    conclusion: str(gateRecord.conclusion),
    verdict_field: str(gateRecord.verdict),
    performance_claimable: bool(gateRecord.performance_claimable),
    required_data_available: bool(gateRecord.required_data_available),
    attempts_launched: num(gateRecord.attempts_launched),
    terminal_sentinels: num(gateRecord.terminal_sentinels),
    decisive_absences: num(gateRecord.decisive_absences),
    matched_current_family: gateMatchedSameFamily,
    shadow_state: token,
    shadow_state_source: token ? 'verbatim token "' + token + '" inside: ' + tokenText : null,
  };
  if (token === null) addGap('gate.shadow_state', 'matched gate record carries no recognised vocabulary token');
}

const asOf = (v) => str(v);
const stages = [];
const push = (o) => stages.push(Object.assign({ order: stages.length + 1 }, o));
const qlibState = (counts.current_stage && RT_TOKENS.indexOf(counts.current_stage) !== -1) ? counts.current_stage : null;
const incidents = Array.isArray(get(obsHealth, 'active')) ? get(obsHealth, 'active').map((i) => ({ kind: str(i.kind), label: str(i.label), first_seen_utc: str(i.first_seen_utc) })) : [];
const topEntries = Array.isArray(get(obsLeaderboard, 'entries')) ? get(obsLeaderboard, 'entries').map((e) => ({ rank: e.rank, cohort: str(e.cohort), sharpe: num(e.sharpe), annualized_return: num(e.annualized_return), max_dd_pct: num(e.max_dd_pct), evidence_state: str(e.evidence_state) })) : null;

const scoutJob = get(scout, 'job');
const scoutDispatch = scoutJob && scoutJob.last_dispatch && typeof scoutJob.last_dispatch === 'object' ? scoutJob.last_dispatch : null;
// Stage 1 projects ONLY the contract whitelist: the ten fixed cron fields (explicit null when the source
// has no value for them) plus last_dispatch when the source actually carries a dispatch record. Source
// readability, file timestamp and provenance notes live in sources[] / gaps, never in the observation.
let researchObs = null;
if (scoutJob && str(scoutJob.job_id)) {
  researchObs = {
    job_id: str(scoutJob.job_id),
    name: str(scoutJob.name),
    enabled: bool(scoutJob.enabled),
    state: str(scoutJob.state),
    schedule_display: str(scoutJob.schedule_display),
    last_run_at: str(scoutJob.last_run_at),
    last_status: str(scoutJob.last_status),
    last_error: str(scoutJob.last_error),
    failure_streak: num(scoutJob.failure_streak),
    next_run_at: str(scoutJob.next_run_at),
  };
  if (scoutDispatch) researchObs.last_dispatch = { scheduled_at: str(scoutDispatch.scheduled_at), dispatched_at: str(scoutDispatch.dispatched_at), lateness_seconds: num(scoutDispatch.lateness_seconds), kind: str(scoutDispatch.kind) };
} else {
  addGap('strategy_research_scout_cron', str(get(scout, 'reason')) || 'scout cron state could not be read or the job was not found');
}
push({ stage: 'strategy_research', label: 'Strategy Research (upstream)', shadow_state: null, state_provenance: null,
  observation: researchObs });
push({ stage: 'github_strategy_pool', label: 'GitHub alpha-strategy-research pool', shadow_state: null, state_provenance: null,
